"""
dedupe_event_stream: Remove duplicate events within a rolling timestamp window.
"""


def _extract_key(event: dict, key_fields: list[str]) -> tuple | None:
    """Return composite key tuple, or None if any field is missing."""
    try:
        return tuple(event[field] for field in key_fields)
    except KeyError:
        return None


def _is_valid(event: dict) -> bool:
    """Return True if event has an integer timestamp."""
    ts = event.get("timestamp")
    return isinstance(ts, int)


def _validate_args(key_fields: list[str], window_seconds: int) -> None:
    """Raise if arguments are invalid."""
    if not isinstance(key_fields, list):
        raise TypeError("key_fields must be a list")
    if not all(isinstance(f, str) for f in key_fields):
        raise TypeError("all elements of key_fields must be strings")
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool):
        raise TypeError("window_seconds must be an integer")
    if window_seconds < 0:
        raise ValueError("window_seconds must be a non-negative integer")


def _classify_event(
    event: dict,
    key_fields: list[str],
    window_seconds: int,
    kept_timestamps: dict[tuple, int],
) -> str:
    """
    Classify a single event as 'malformed', 'duplicate', or 'keep'.

    Also updates kept_timestamps when the event is to be kept.
    """
    if not _is_valid(event):
        return "malformed"

    key = _extract_key(event, key_fields)
    if key is None:
        return "malformed"

    ts: int = event["timestamp"]

    if key in kept_timestamps:
        last_kept_ts = kept_timestamps[key]
        if (ts - last_kept_ts) < window_seconds:
            return "duplicate"

    kept_timestamps[key] = ts
    return "keep"


def dedupe_events(
    events: list[dict],
    key_fields: list[str],
    window_seconds: int,
    return_stats: bool = False,
) -> "list[dict] | tuple[list[dict], dict[str, int]]":
    """
    Deduplicate events by composite key within a rolling timestamp window.

    Keeps the first occurrence of each composite key. Any subsequent event
    with the same composite key whose timestamp falls within window_seconds
    of the kept event's timestamp is considered a duplicate and discarded.

    Args:
        events: Sequence of event dicts, each expected to have 'timestamp'
                (int) and all key_fields present.
        key_fields: Field names that together form the composite dedup key.
        window_seconds: Duration in seconds defining the dedup window.
        return_stats: If True, return a tuple of (retained_events, stats_dict)
                      where stats_dict contains 'kept', 'duplicates', and
                      'malformed' counts.

    Returns:
        List of retained events in original order, or a tuple of
        (retained_events, stats) when return_stats is True.

    Raises:
        TypeError: If events is not a list, key_fields is not a list of strings,
                   window_seconds is not an integer, or return_stats is not bool.
        ValueError: If window_seconds is negative.
    """
    if not isinstance(events, list):
        raise TypeError("events must be a list")
    if not isinstance(return_stats, bool):
        raise TypeError("return_stats must be a boolean")

    _validate_args(key_fields, window_seconds)

    for i, event in enumerate(events):
        if not isinstance(event, dict):
            raise TypeError(f"each event must be a dict; got non-dict at index {i}")

    kept_timestamps: dict[tuple, int] = {}
    retained: list[dict] = []
    kept_count = 0
    duplicates_count = 0
    malformed_count = 0

    for event in events:
        classification = _classify_event(
            event, key_fields, window_seconds, kept_timestamps
        )
        if classification == "malformed":
            malformed_count += 1
        elif classification == "duplicate":
            duplicates_count += 1
        else:
            retained.append(event)
            kept_count += 1

    if return_stats:
        stats = {
            "kept": kept_count,
            "duplicates": duplicates_count,
            "malformed": malformed_count,
        }
        return retained, stats

    return retained

